window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[217]={"id":"217","numero":217,"titre":"Syndrome mononucléosique","objectifs":[{"id":"217-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome mononucléosique","contenu":"<p>Le <span class=\"kw-def\">syndrome mononucléosique</span> est un syndrome <strong>hématologique</strong> défini par une anomalie à la fois <strong>quantitative</strong> et <strong>qualitative</strong> de la lignée lymphocytaire. Son diagnostic repose impérativement sur l'<strong>association de deux examens</strong> : la <span class=\"kw-bio\">NFS</span> et le <span class=\"kw-bio\">frottis sanguin</span> — l'un sans l'autre ne suffit pas à l'affirmer.</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Critère définissant</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS</span></td>\n            <td>\n              <strong>Hyperlymphocytose modérée :</strong> <span class=\"kw-chiffre\">&gt; 4 G/L</span> chez l'enfant de plus de <span class=\"kw-chiffre\">12 ans</span> et chez l'adulte, mais restant <span class=\"kw-chiffre\">&lt; 30 G/L</span><br>\n              <strong>Cellules mononuclées :</strong> <span class=\"kw-chiffre\">&gt; 50 %</span> des <span class=\"kw-bio\">leucocytes</span> sont des cellules mononuclées (<span class=\"kw-bio\">lymphocytes</span> + <span class=\"kw-bio\">monocytes</span>, par opposition aux <span class=\"kw-bio\">polynucléaires</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Frottis sanguin</span></td>\n            <td>\n              <strong>Cellules activées :</strong> présence de <span class=\"kw-chiffre\">≥ 10 %</span> de cellules mononuclées <strong>activées</strong><br>\n              <strong>Sémiologie détaillée :</strong> cf. <em>obj-1 — Caractéristiques du <span class=\"kw-bio\">frottis sanguin</span></em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong>autres lignées</strong> (érythrocytaire, plaquettaire) sont <strong>normales</strong> : c'est un argument fort contre une <span class=\"kw-alerte\">hémopathie maligne</span>. <span class=\"kw-alerte\">Très rarement</span>, une forme grave peut s'accompagner d'une <span class=\"kw-clinique\">anémie hémolytique auto-immune (AHAI)</span>, d'une <span class=\"kw-clinique\">thrombopénie auto-immune</span>, voire d'une <span class=\"kw-clinique\">pancytopénie</span>.</p>\n      <p><strong><span class=\"kw-clinique\">Évolution</span> :</strong> l'hyperlymphocytose est <strong>polymorphe</strong> et <span class=\"kw-clinique\">régresse spontanément</span> en <span class=\"kw-chiffre\">quelques semaines</span> — le syndrome mononucléosique est de caractère <strong>bénin et transitoire</strong>.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> En pratique, on observe fréquemment seulement <span class=\"kw-chiffre\">5 à 10 %</span> de <span class=\"kw-bio\">lymphocytes</span> activés sur le frottis. Ce résultat <strong>n'entre pas dans la définition stricte</strong> du syndrome mononucléosique, mais témoigne d'une réponse anti-infectieuse ou immune et peut avoir, en pratique, la même signification.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 215 — <span class=\"kw-def\">Purpura</span> · 218 — Eosinophilie</em></p>","frequence":4},{"id":"217-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques du frottis sanguin","contenu":"<p>Le <span class=\"kw-bio\">frottis sanguin</span> est l'examen <strong>clé</strong> du syndrome mononucléosique : il met en évidence <span class=\"kw-clinique\">les</span> cellules mononuclées <strong>activées</strong> (<span class=\"kw-chiffre\">≥ 10 %</span> des <span class=\"kw-bio\">leucocytes</span>). Ces cellules sont des <span class=\"kw-def\">lymphocytes T activés</span> par une stimulation antigénique en réponse à un pathogène, le plus souvent <strong><span class=\"kw-etio\">viral</span></strong>. Leur reconnaissance impose de les distinguer formellement des <span class=\"kw-bio\">lymphocytes</span> de la <span class=\"kw-etio\">leucémie lymphoïde chronique (LLC)</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Caractère cytologique</th><th>Syndrome mononucléosique</th><th>Leucémie lymphoïde chronique (LLC)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Nature cellulaire</td><td><span class=\"kw-def\">Lymphocytes T activés</span> — réaction immune réactionnelle</td><td><span class=\"kw-bio\">Lymphocytes B</span> monoclonaux — prolifération <span class=\"kw-etio\">tumorale</span></td></tr>\n          <tr><td>Cytoplasme</td><td><strong>Hyperbasophile</strong> — témoin de l'activité cellulaire</td><td>Peu abondant, non hyperbasophile</td></tr>\n          <tr><td>Morphologie</td><td><strong>Polymorphes</strong> — cellules d'aspects variés</td><td><strong>Monomorphes</strong> — population uniforme</td></tr>\n          <tr><td>Taille</td><td><strong>Grande taille</strong></td><td><strong>Petite taille</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Autres anomalies possibles selon l'étiologie</strong> — le frottis peut aussi montrer :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Cellules en apoptose</span> — évocatrices d'une <span class=\"kw-etio\">mononucléose infectieuse (MNI)</span> à <span class=\"kw-etio\">EBV</span>.</li>\n        <li><span class=\"kw-clinique\">Cellules lymphoplasmocytaires</span> et <span class=\"kw-clinique\">plasmocytes</span> — évocateurs d'une <span class=\"kw-etio\">rubéole</span> ou d'un <span class=\"kw-etio\">DRESS</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Le frottis du syndrome mononucléosique ne contient <strong>pas de cellules blastiques</strong> et <span class=\"kw-clinique\">les</span> autres cellules non lymphoïdes sont <strong>morphologiquement normales</strong>. La présence de <span class=\"kw-alerte\">blastes</span> doit faire évoquer une <span class=\"kw-alerte\">leucémie aiguë</span> — et non un syndrome mononucléosique.\n      </div>","frequence":2},{"id":"217-3","rang":"B","rubrique":"Contenu multimédia","titre":"Photo de frottis sanguin","contenu":"<div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune image de <span class=\"kw-bio\">frottis sanguin</span> n'a été fournie dans la fiche source pour cet objectif. La sémiologie cytologique attendue (LT activés, cytoplasme hyperbasophile, polymorphes, grande taille) est couverte par <a href=\"#obj-1\">obj-1 — Caractéristiques du frottis sanguin</a>. Kevin fournira ultérieurement une image (Pilly, Collège, ou photo personnelle) via B-FIX dédié.\n      </div>","frequence":1},{"id":"217-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire chez un patient présentant un syndrome mononucléosique","contenu":"<p>Devant un syndrome mononucléosique, l'<strong>interrogatoire</strong> est le <strong>premier temps</strong> de l'orientation étiologique. Quelques questions ciblées suffisent souvent à orienter d'emblée vers l'un des grands agents responsables.</p>\n      <table >\n        <thead>\n          <tr><th>Élément interrogé</th><th>Orientation étiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td>Le syndrome mononucléosique touche majoritairement l'<strong>enfant</strong> et le <strong>jeune adulte</strong></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Contage avec de jeunes enfants</span></strong></td><td><span class=\"kw-etio\">CMV</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Nouvelle relation amoureuse</span></strong></td><td><span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Rapports sexuels à risque</span></strong> ou <strong><span class=\"kw-clinique\">toxicomanie IV</span></strong></td><td><span class=\"kw-etio\">VIH</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Contact avec un chat</span></strong>, aliments souillés par un chat, ou consommation de <strong>viande crue</strong></td><td><span class=\"kw-etio\">Toxoplasmose</span></td></tr>\n          <tr><td><strong>Introduction récente d'un médicament</strong></td><td><span class=\"kw-etio\">Toxidermie</span> (cause non infectieuse)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant une <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">CMV</span>, il faut systématiquement <strong>rechercher une femme enceinte dans l'entourage</strong> : le <span class=\"kw-etio\">CMV</span> est la première cause d'infection <span class=\"kw-etio\">congénitale</span> et expose à un risque d'<span class=\"kw-alerte\">embryofœtopathie</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 168 — Herpesvirus</em></p>","frequence":1},{"id":"217-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies infectieuses d’un syndrome mononucléosique et leurs moyens diagnostiques (Epstein Barr virus (EBV), Cytomégalovirus (CMV), Virus de l’immunodéficience humaine (VIH), toxoplasmose)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">étiologies infectieuses</span> dominent très largement le syndrome mononucléosique. <strong>Quatre agents</strong> doivent être connus en priorité — <span class=\"kw-etio\">EBV</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">VIH</span> et <span class=\"kw-etio\">Toxoplasma gondii</span> — car ils représentent l'immense majorité des cas et appellent chacun des <strong>moyens diagnostiques spécifiques</strong>.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">Fréquence relative des 4 étiologies majeures</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Agent</th><th>Part des syndromes mononucléosiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Primo-infection</span> <span class=\"kw-etio\">EBV</span></strong></td><td><span class=\"kw-etio\">Epstein-Barr virus</span> — mononucléose infectieuse (MNI)</td><td><span class=\"kw-chiffre\">≈ 80 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Primo-infection</span> <span class=\"kw-etio\">CMV</span></strong></td><td><span class=\"kw-etio\">Cytomégalovirus</span></td><td><span class=\"kw-chiffre\">5 à 10 %</span></td></tr>\n          <tr><td><strong>Toxoplasmose</strong></td><td><span class=\"kw-etio\">Toxoplasma gondii</span></td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Primo-infection</span> <span class=\"kw-etio\">VIH</span></strong></td><td><span class=\"kw-etio\">Virus de l'immunodéficience humaine</span></td><td><span class=\"kw-chiffre\">Rare</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">Tableau d'orientation devant un syndrome mononucléosique</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th><span class=\"kw-etio\">EBV</span></th><th><span class=\"kw-etio\">CMV</span></th><th><span class=\"kw-etio\">VIH</span></th><th><span class=\"kw-etio\">Toxoplasma gondii</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Population</strong></td>\n            <td>Adolescent, adulte jeune</td>\n            <td>Adulte jeune</td>\n            <td>Adolescents et adultes de tous âges</td>\n            <td>Enfant, adolescent et adulte jeune</td>\n          </tr>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>Nouveau partenaire</td>\n            <td>Notion de contage</td>\n            <td><span class=\"kw-clinique\">Rapport sexuel à risque</span>, drogue IV</td>\n            <td><span class=\"kw-def\">Contact</span> chat, viande crue ou peu cuite</td>\n          </tr>\n          <tr>\n            <td><strong>Incubation</strong></td>\n            <td><span class=\"kw-chiffre\">4 à 6 semaines</span></td>\n            <td><span class=\"kw-chiffre\">3 à 8 semaines</span></td>\n            <td><span class=\"kw-chiffre\">2 à 8 semaines</span></td>\n            <td><span class=\"kw-chiffre\">5 jours à 3 semaines</span></td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td><span class=\"kw-clinique\">Angine pseudomembraneuse</span>, <span class=\"kw-clinique\">polyadénopathie</span>, <span class=\"kw-clinique\">splénomégalie</span>, <span class=\"kw-clinique\">éruption sous aminopénicilline</span></td>\n            <td><span class=\"kw-clinique\">Fièvre isolée ± prolongée</span>, <span class=\"kw-clinique\">adénopathies cervicales</span>, <span class=\"kw-clinique\">splénomégalie</span></td>\n            <td>Nombreux tableaux : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">éruption cutanée</span>, <span class=\"kw-clinique\">pharyngite</span>, <span class=\"kw-clinique\">ulcérations muqueuses</span>, <span class=\"kw-clinique\">polyadénopathie</span></td>\n            <td><span class=\"kw-clinique\">Adénopathies cervicales postérieures</span></td>\n          </tr>\n          <tr>\n            <td><strong>Intensité du syndrome</strong></td>\n            <td><span class=\"kw-chiffre\">+++</span></td>\n            <td><span class=\"kw-chiffre\">++</span></td>\n            <td><span class=\"kw-chiffre\">+</span></td>\n            <td><span class=\"kw-chiffre\">±</span></td>\n          </tr>\n          <tr>\n            <td><strong>Diagnostic</strong></td>\n            <td><span class=\"kw-bio\">MNI-test</span> en 1<sup>re</sup> intention, <span class=\"kw-bio\">sérologie</span> spécifique si négatif</td>\n            <td><span class=\"kw-bio\">Sérologie CMV</span> spécifique</td>\n            <td><span class=\"kw-bio\">Sérologie VIH</span> combinée + charge <span class=\"kw-etio\">virale</span></td>\n            <td><span class=\"kw-bio\">Sérologie toxoplasmose</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">Moyens diagnostiques spécifiques</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Stratégie diagnostique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">EBV</span></td>\n            <td>\n              <strong>1<sup>re</sup> intention :</strong> <span class=\"kw-bio\">MNI-test</span> (recherche d'anticorps hétérophiles)<br>\n              <strong>2<sup>e</sup> intention si négatif :</strong> <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">EBV</span> spécifique (<span class=\"kw-bio\">IgM anti-VCA</span>, <span class=\"kw-bio\">IgG anti-VCA</span>, <span class=\"kw-bio\">IgG anti-EBNA</span>)<br>\n              <strong>Interprétation :</strong> <span class=\"kw-clinique\">primo-infection</span> = <span class=\"kw-bio\">IgM anti-VCA</span> présentes ; <span class=\"kw-bio\">IgG anti-EBNA</span> absentes au début, apparaissent secondairement\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">CMV</span></td>\n            <td>\n              <strong>Diagnostic :</strong> <span class=\"kw-bio\">sérologie CMV</span> spécifique (<span class=\"kw-bio\">IgM</span> + <span class=\"kw-bio\">IgG</span>)<br>\n              <strong><span class=\"kw-clinique\">Primo-infection</span> :</strong> <span class=\"kw-bio\">IgM</span> positives ± séroconversion des <span class=\"kw-bio\">IgG</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">VIH</span></td>\n            <td>\n              <strong><span class=\"kw-def\">Dépistage</span> :</strong> <span class=\"kw-bio\">sérologie VIH combinée</span> (anticorps + <span class=\"kw-bio\">antigène p24</span>)<br>\n              <strong>Si fenêtre sérologique :</strong> <span class=\"kw-bio\">PCR VIH</span> (charge <span class=\"kw-etio\">virale</span>), positive avant l'apparition des anticorps\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Toxoplasmose</span></td>\n            <td>\n              <strong>Diagnostic :</strong> <span class=\"kw-bio\">sérologie toxoplasmose</span> (<span class=\"kw-bio\">IgM</span> + <span class=\"kw-bio\">IgG</span>)<br>\n              <strong>Datation :</strong> mesure de l'<span class=\"kw-bio\">avidité des IgG</span> si nécessaire pour dater l'infection\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Devant <strong>tout</strong> syndrome mononucléosique, la <span class=\"kw-bio\">sérologie VIH</span> est <strong>systématique</strong> : la <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VIH</span> est statistiquement rare mais ne doit <strong>jamais</strong> être méconnue (enjeu individuel + santé publique). En tout début d'infection, <span class=\"kw-clinique\">les</span> anticorps peuvent être absents (<span class=\"kw-alerte\">fenêtre sérologique</span>) — c'est alors la <span class=\"kw-bio\">PCR VIH</span> et l'<span class=\"kw-bio\">antigène p24</span> qui font le diagnostic.\n      </div>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <span class=\"kw-clinique\">éruption cutanée maculo-papuleuse</span> survenant après prise d'<span class=\"kw-ttt\">aminopénicilline</span> (<span class=\"kw-ttt\">amoxicilline</span> / <span class=\"kw-ttt\">ampicilline</span>) au cours d'une angine = <strong>« faux <span class=\"kw-clinique\">rash</span> à l'ampicilline »</strong>, évocateur d'une <span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">EBV</span>. Ce n'est <strong>pas une <span class=\"kw-ci\">allergie</span></strong> aux pénicillines : le patient pourra ré-en recevoir ultérieurement.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 168 — Herpesvirus · 170 — <span class=\"kw-clinique\">Paludisme</span> · 167 — Hépatites virales</em></p>","frequence":5},{"id":"217-6","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales étiologies non infectieuses de syndrome mononucléosique","contenu":"<p>Au-delà des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>randes étiologies infectieuses (cf. obj-4), un syndrome mononucléosique peut relever de causes <strong>non infectieuses</strong>, ou d'autres causes infectieuses plus rares. Leur recherche ne dispense jamais d'éliminer d'abord <span class=\"kw-clinique\">les</span> causes virales fréquentes.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">Étiologies non infectieuses</h4>\n      <table >\n        <thead>\n          <tr><th>Cadre</th><th>Causes</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ci\">Allergie</span> médicamenteuse</strong></td><td><span class=\"kw-etio\">DRESS syndrome</span> (<span class=\"kw-alerte\">toxidermie grave</span>)</td></tr>\n          <tr><td><strong>Réactions immunologiques</strong></td><td><span class=\"kw-etio\">Maladie du greffon contre l'hôte (GVH)</span> ; <span class=\"kw-etio\">maladie sérique</span></td></tr>\n          <tr><td><strong>Maladies auto-immunes</strong></td><td><span class=\"kw-etio\">Lupus systémique</span> ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Identifier une cause <span class=\"kw-etio\">auto-immune</span> <strong>n'empêche pas</strong> de rechercher en parallèle une <span class=\"kw-etio\">étiologie infectieuse</span> ou <span class=\"kw-etio\">médicamenteuse</span>, qui peut coexister dans ce contexte.\n      </div>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">Autres étiologies infectieuses (non-virales et virales plus rares)</h4>\n      <table >\n        <thead>\n          <tr><th>Type d'agent</th><th>Causes</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Bactériennes</strong></td><td><span class=\"kw-etio\">Rickettsiose</span>, <span class=\"kw-etio\">brucellose</span>, <span class=\"kw-etio\">listériose</span>, <span class=\"kw-etio\">syphilis secondaire</span>, <span class=\"kw-etio\">typhoïde</span></td></tr>\n          <tr><td><strong>Parasitaires</strong></td><td><span class=\"kw-etio\">Paludisme</span></td></tr>\n          <tr><td><strong>Virales</strong></td><td><span class=\"kw-etio\">Hépatites virales aiguës</span> (<span class=\"kw-def\">hépatite</span> A essentiellement) ; <span class=\"kw-etio\">rubéole</span> et autres maladies éruptives de l'enfance (<span class=\"kw-etio\">HHV6</span>) ; <span class=\"kw-etio\">dengue</span> ; <span class=\"kw-etio\">parvovirus B19</span> ; <span class=\"kw-etio\">adénovirus</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 115 — Toxidermies · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 211 — <span class=\"kw-clinique\">Sarcoïdose</span></em></p>","frequence":1}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-217.pdf","label":"Pilly étudiant — Pilly 2023 item 217"}],"cards":[{"i":"1c46edf16e9e","n":217,"o":"217-1","u":"Définition","t":"Connaître la définition du syndrome mononucléosique","q":"Quels sont les examens indispensables au diagnostic du syndrome mononucléosique et pourquoi ?","a":"<p>Le diagnostic du syndrome mononucléosique repose impérativement sur l'association de <strong>deux examens indissociables</strong> : la Numération Formule Sanguine (NFS) et le frottis sanguin. L'un sans l'autre ne suffit pas à l'affirmer.</p>"},{"i":"269f8f8c8f09","n":217,"o":"217-1","u":"Définition","t":"Connaître la définition du syndrome mononucléosique","q":"Quelle est l'évolution habituelle du syndrome mononucléosique ?","a":"<p>L'hyperlymphocytose est polymorphe et <strong>régresse spontanément en quelques semaines</strong>, attestant du caractère <strong>bénin et transitoire</strong> du syndrome mononucléosique.</p>"},{"i":"2cdd9427c58e","n":217,"o":"217-1","u":"Définition","t":"Connaître la définition du syndrome mononucléosique","q":"Quelle est la définition générale du syndrome mononucléosique ?","a":"<p>Le syndrome mononucléosique est un <strong>syndrome hématologique</strong> défini par une anomalie quantitative et qualitative de la <strong>lignée lymphocytaire</strong>.</p>"},{"i":"347f30567a7b","n":217,"o":"217-1","u":"Définition","t":"Connaître la définition du syndrome mononucléosique","q":"Quel est le critère diagnostique du syndrome mononucléosique sur le frottis sanguin ?","a":"<p>Le frottis sanguin doit montrer la présence d'au moins <strong>10% de cellules mononuclées activées</strong>.</p>"},{"i":"c5719fdaa43d","n":217,"o":"217-1","u":"Définition","t":"Connaître la définition du syndrome mononucléosique","q":"Quels sont les critères diagnostiques du syndrome mononucléosique à la NFS chez l'adulte et l'enfant de plus de 12 ans ?","a":"<ul><li>Une <strong>hyperlymphocytose modérée</strong> : la numération des lymphocytes est <strong>supérieure à 4 G/L</strong> mais reste <strong>inférieure à 30 G/L</strong>.</li><li>La proportion de <strong>cellules mononuclées est supérieure à 50%</strong> des leucocytes (lymphocytes + monocytes).</li></ul>"},{"i":"c5f697c70672","n":217,"o":"217-1","u":"Définition","t":"Connaître la définition du syndrome mononucléosique","q":"Comment les autres lignées sanguines (érythrocytaire et plaquettaire) se comportent-elles généralement dans un syndrome mononucléosique ?","a":"<p>Dans un syndrome mononucléosique typique, les autres lignées (érythrocytaire et plaquettaire) sont <strong>normales</strong>, ce qui est un argument fort contre une hémopathie maligne.</p>"},{"i":"025fcd42edde","n":217,"o":"217-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire chez un patient présentant un syndrome mononucléosique","q":"Pourquoi est-il important de rechercher l'introduction récente d'un médicament dans l'interrogatoire d'un patient avec un syndrome mononucléosique ?","a":"<p>L'introduction récente d'un médicament peut orienter vers une <strong>toxidermie</strong>, qui est une cause non infectieuse de syndrome mononucléosique.</p>"},{"i":"1d2cc0ff5a76","n":217,"o":"217-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire chez un patient présentant un syndrome mononucléosique","q":"Quelles questions d'interrogatoire peuvent orienter vers une étiologie virale spécifique (EBV, CMV, VIH) ou une toxoplasmose face à un syndrome mononucléosique ?","a":"<ul><li>Une <strong>nouvelle relation amoureuse</strong> peut orienter vers l'<strong>EBV</strong> ou le <strong>CMV</strong>.</li><li>Des <strong>rapports sexuels à risque</strong> ou une <strong>toxicomanie IV</strong> orientent vers le <strong>VIH</strong>.</li><li>Un <strong>contage avec de jeunes enfants</strong> peut orienter vers le <strong>CMV</strong>.</li><li>Un <strong>contact avec un chat</strong>, des aliments souillés par un chat, ou la consommation de viande crue orientent vers la <strong>toxoplasmose</strong>.</li></ul>"},{"i":"5cb182fe71f9","n":217,"o":"217-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire chez un patient présentant un syndrome mononucléosique","q":"Pourquoi doit-on systématiquement rechercher une femme enceinte dans l'entourage d'un patient atteint de primo-infection à CMV ?","a":"<p>Il est crucial de rechercher une <strong>femme enceinte</strong> dans l'entourage car le <strong>CMV</strong> est la <strong>première cause d'infection congénitale</strong> et expose à un risque d'<strong>embryofœtopathie</strong>.</p>"},{"i":"b97d656f3ad4","n":217,"o":"217-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire chez un patient présentant un syndrome mononucléosique","q":"Quel élément de l'interrogatoire est essentiel concernant l'âge d'un patient présentant un syndrome mononucléosique ?","a":"<p>L'<strong>âge</strong> est un élément important car le syndrome mononucléosique touche majoritairement l'<strong>enfant</strong> et le <strong>jeune adulte</strong>.</p>"},{"i":"0d8fcaa132ab","n":217,"o":"217-5","u":"Étiologies","t":"Connaître les principales étiologies infectieuses d’un syndrome mononucléosique et leurs moyens diagnostiques (Epstein Barr virus (EBV), Cytomégalovirus (CMV), Virus de l’immunodéficience humaine (VIH), toxoplasmose)","q":"Quels sont les éléments cliniques permettant d'orienter vers une primo-infection EBV, CMV, VIH ou Toxoplasma gondii devant un syndrome mononucléosique ?","a":"<ul><li><strong>EBV</strong> (Mononucléose Infectieuse) : <strong>adolescent, adulte jeune</strong>, incubation 4 à 6 semaines, <strong>angine pseudomembraneuse</strong>, <strong>polyadénopathie</strong>, <strong>splénomégalie</strong>, <strong>éruption sous aminopénicilline</strong>. Syndrome très intense.</li><li><strong>CMV</strong> : adulte jeune, incubation 3 à 8 semaines, <strong>fièvre isolée ± prolongée</strong>, adénopathies cervicales, splénomégalie. Syndrome modérément intense.</li><li><strong>VIH</strong> : adolescents et adultes de tous âges, notion de <strong>rapport sexuel à risque</strong> ou <strong>drogue IV</strong>, incubation 2 à 8 semaines, tableaux variés (fièvre, myalgies, arthralgies, éruption cutanée, pharyngite, ulcérations muqueuses, polyadénopathie). Syndrome peu intense.</li><li><strong>Toxoplasma gondii</strong> : enfant, adolescent et adulte jeune, notion de <strong>contact chat</strong> ou <strong>viande crue/mal cuite</strong>, incubation 5 jours à 3 semaines, <strong>adénopathies cervicales postérieures</strong>. Syndrome peu intense.</li></ul>"},{"i":"89001865abac","n":217,"o":"217-5","u":"Étiologies","t":"Connaître les principales étiologies infectieuses d’un syndrome mononucléosique et leurs moyens diagnostiques (Epstein Barr virus (EBV), Cytomégalovirus (CMV), Virus de l’immunodéficience humaine (VIH), toxoplasmose)","q":"Quel est le piège classique à connaître concernant une éruption cutanée maculo-papuleuse chez un patient sous aminopénicilline et présentant un syndrome mononucléosique ?","a":"<p>Le piège classique est le « <strong>faux rash à l'ampicilline</strong> » : une <strong>éruption cutanée maculo-papuleuse</strong> survenant après la prise d'une <strong>aminopénicilline (amoxicilline / ampicilline)</strong> au cours d'une angine est très évocatrice d'une <strong>primo-infection EBV</strong>. Ce n'est pas une allergie aux pénicillines et le patient pourra recevoir à nouveau ces molécules ultérieurement.</p>"},{"i":"c0cbd41e370c","n":217,"o":"217-5","u":"Étiologies","t":"Connaître les principales étiologies infectieuses d’un syndrome mononucléosique et leurs moyens diagnostiques (Epstein Barr virus (EBV), Cytomégalovirus (CMV), Virus de l’immunodéficience humaine (VIH), toxoplasmose)","q":"Quelles sont les quatre principales étiologies infectieuses à évoquer devant un syndrome mononucléosique et leur fréquence relative ?","a":"<p>Les quatre principales étiologies infectieuses à évoquer devant un syndrome mononucléosique sont :</p><ul><li>La primo-infection par l'<strong>EBV</strong> (mononucléose infectieuse) : <strong>environ 80 %</strong> des cas.</li><li>La primo-infection par le <strong>CMV</strong> (Cytomégalovirus) : <strong>5 à 10 %</strong> des cas.</li><li>La <strong>toxoplasmose</strong> : <strong>moins de 1 %</strong> des cas.</li><li>La primo-infection <strong>VIH</strong> : <strong>rare</strong>.</li></ul>"},{"i":"fc29b182ccf9","n":217,"o":"217-5","u":"Étiologies","t":"Connaître les principales étiologies infectieuses d’un syndrome mononucléosique et leurs moyens diagnostiques (Epstein Barr virus (EBV), Cytomégalovirus (CMV), Virus de l’immunodéficience humaine (VIH), toxoplasmose)","q":"Quelle est la stratégie diagnostique spécifique pour la primo-infection EBV, CMV, VIH et Toxoplasma gondii en cas de syndrome mononucléosique ?","a":"<ul><li><strong>EBV</strong> : En 1<sup>re</sup> intention, le <strong>MNI-test</strong> (recherche d'anticorps hétérophiles). En 2<sup>e</sup> intention si négatif, la <strong>sérologie EBV spécifique</strong> (IgM anti-VCA, IgG anti-VCA, IgG anti-EBNA). Une primo-infection est caractérisée par la présence d'<strong>IgM anti-VCA</strong> et l'absence initiale d'IgG anti-EBNA.</li><li><strong>CMV</strong> : La <strong>sérologie CMV spécifique</strong> (IgM + IgG). Une primo-infection est marquée par des <strong>IgM positives</strong> et/ou une séroconversion des IgG.</li><li><strong>VIH</strong> : Dépistage par <strong>sérologie VIH combinée (anticorps + antigène p24)</strong>. En cas de suspicion et de fenêtre sérologique (anticorps absents), la <strong>PCR VIH</strong> (charge virale) confirmera le diagnostic. La sérologie VIH est <strong>systématique</strong> devant tout syndrome mononucléosique.</li><li><strong>Toxoplasmose</strong> : La <strong>sérologie toxoplasmose</strong> (IgM + IgG). La datation de l'infection peut être précisée par la mesure de l'<strong>avidité des IgG</strong>.</li></ul>"}]};